ST.xhtml:
Time_Dat:=TargetVars.stRtc.dtDateAndTime;
IF POU_V.DAT THEN
T1    :=POU_V.T1   	;(*Температура Байпас 1*)
T3    :=POU_V.T3   	;(*Температура до циклона 1*)
T4    :=POU_V.T4   	;(*Температура до циклона 2*)
T5    :=POU_V.T5   	;(*Температура шахта +12*)
T6    :=POU_V.T6   	;(*Темпкратура шахта +16*)
T7    :=POU_V.T7   	;(*Температура шахта +21*)
T8    :=POU_V.T8   	;(*Температура шахта+ 9*)
T9    :=POU_V.T9   	;(*Температура после циклона*)
T11   :=POU_V.T11  	;(*Температура после вентилятора*)
T12   :=POU_V.T12  	;(*Температура перед дымососом*)
T13   :=POU_V.T13  	;(*Температура в топке ТХА*)
T14   :=POU_V.T14  	;(*Температура перед шахтой ТХА*)
T15   :=POU_V.T15  	;(*Температура +21 ТХА*)
T16   :=POU_V.T16  	;(*Температура в цехе*)
D1    :=POU_V.D1   	;(*Разряжение в топке*)
D2    :=POU_V.D2   	;(*Давление газа нагорелку*)
D3    :=POU_V.D3   	;(*Давление воздуха в коллекторе перед горелкой(аг)*)
D4    :=POU_V.D4   	;(*Давление на разбавление*)
D5    :=POU_V.D5    ;(*Давление после вентилятора*)
D6    :=POU_V.D6    ;(*Разряжение после дымососа*)
D8    :=POU_V.D8   	;(*Разряжение после циклона*)
D9    :=POU_V.D9   	;(*Разряжение в топке(аг)*)
D10   :=POU_V.D10  	;(*Давление воздуха перед горелкой(аг)*)
PIT:=POU_V.PIT_1	;(*Загрузка питателя,%/100*)
 ELSE
T1:= OSCAT_BASIC.ROUND (FILTR.T1_F ,1);
T3:= OSCAT_BASIC.ROUND (FILTR.T3_F ,1);
T4:= OSCAT_BASIC.ROUND (FILTR.T4_F ,1);
T5:= OSCAT_BASIC.ROUND (FILTR.T5_F ,1);
T6:= OSCAT_BASIC.ROUND (FILTR.T6_F ,1);
T7:= OSCAT_BASIC.ROUND (FILTR.T7_F ,1);
T8:= OSCAT_BASIC.ROUND (FILTR.T8_F ,1);
T9:= OSCAT_BASIC.ROUND (FILTR.T9_F ,1);
T11:= OSCAT_BASIC.ROUND (FILTR.T11_F ,1);
T12:= OSCAT_BASIC.ROUND (FILTR.T12_F ,1);
T13:= OSCAT_BASIC.ROUND (FILTR.T13_F ,1);
T14:= OSCAT_BASIC.ROUND (FILTR.T14_F ,1);
T15:= OSCAT_BASIC.ROUND (FILTR.T15_F ,1);
T16:= OSCAT_BASIC.ROUND (FILTR.T16_F ,1);
D1:= OSCAT_BASIC.ROUND (FILTR.D1_F ,0);
D2:= OSCAT_BASIC.ROUND (FILTR.D2_F ,0);
D3:= OSCAT_BASIC.ROUND (FILTR.D3_F ,0);
D4:= OSCAT_BASIC.ROUND (FILTR.D4_F ,0);
D5:= OSCAT_BASIC.ROUND (FILTR.D5_F ,0);
D6:= OSCAT_BASIC.ROUND (FILTR.D6_F ,0);
D8:= OSCAT_BASIC.ROUND (FILTR.D8_F ,0);
D9:= OSCAT_BASIC.ROUND (FILTR.D9_F ,0);
D10:= OSCAT_BASIC.ROUND (FILTR.D10_F ,0);
VL_air:= OSCAT_BASIC.ROUND (FILTR.VL_air_F ,0);
PIT:= OSCAT_BASIC.ROUND (FILTR.PIT_F,1)/100;	

WT1:=REAL_TO_WORD (T1);
WT3:=REAL_TO_WORD (T3);
WT4:=REAL_TO_WORD (T4);
WT5:=REAL_TO_WORD (T5);
WT6:=REAL_TO_WORD (T6);
WT7:=REAL_TO_WORD (T7);
WT8:=REAL_TO_WORD (T8);
WT9:=REAL_TO_WORD (T9);
WT11:=REAL_TO_WORD (T11);
WT12:=REAL_TO_WORD (T12);
WT13:=REAL_TO_WORD (T13);
WT14:=REAL_TO_WORD (T14);
WT15:=REAL_TO_WORD (T15);
WD1:=REAL_TO_WORD (D1);
WD2:=REAL_TO_WORD (D2);
WD3:=REAL_TO_WORD (D3);
WD4:=REAL_TO_WORD (D4);
WD5:=REAL_TO_WORD (D5);
WD6:=REAL_TO_WORD (D6);
WD8:=REAL_TO_WORD (D8);
WD9:=REAL_TO_WORD (D9);
WD10:=REAL_TO_WORD (D10);
WPIT:=REAL_TO_WORD (PIT*100);
Q_gazW:=REAL_TO_WORD (Q_gaz);
END_IF

IF D2>50 THEN gor:= TRUE; Q_gaz:=OSCAT_BASIC.ROUND (GAZ.R1_imp,1);
ELSE Q_gaz:=0; gor:= FALSE; END_IF

// Установка флага работы дымососа и текста сообщения
IF D6<-200 THEN Dym:=TRUE; Dym_w:=WCONCAT (WCONCAT("Дымосос включен, разряжение в топке ",REAL_TO_WSTRING(d9))," Па"); ELSE Dym:=FALSE; Dym_w:= "Дымосос выключен"; END_IF

// Установка флага работы вентилятора и текста сообщения
IF D2+D3+D4+D5>500 THEN	Vent:=TRUE; Vent_w:=WCONCAT (WCONCAT("Вентилятор включен, давление в коллекторе ",REAL_TO_WSTRING(d3))," Па"); ELSE Vent:=FALSE; Vent_w:= "Вентилятор выключен"; END_IF

// Установка флага работы горелки и текста сообщения
IF Gor=TRUE THEN Gor_w:=WCONCAT (WCONCAT("Горелка включена, давление перед горелкой ",REAL_TO_WSTRING(D2))," Па"); ELSE Gor_w:= "Горелка выключена"; END_IF

// Установка флага работы питателя и текста сообщения
IF POU_V.PIT_1>0.01 THEN Pitat:=TRUE;Pitat_w:= WCONCAT (WCONCAT("Питатель включен, загрузка ",REAL_TO_WSTRING(OSCAT_BASIC.ROUND(PIT*100,2))),"%"); ELSE Pitat:=FALSE; Pitat_w:= "Питатель выключен"; END_IF

// Установка флага работы печи без загрузки и текста сообщения
//IF Gor=TRUE AND ((T15>T1 OR T8-10>T1) OR Pitat=FALSE) THEN No_Rud:=TRUE; ELSE No_Rud:=FALSE; END_IF
IF Dym=TRUE AND Vent=TRUE AND Pitat=FALSE THEN No_Rud:=TRUE; ELSE No_Rud:=FALSE; END_IF

// Установка флага работы печи с недостаточным количеством воздуха (влажность на какой-то отметке больше 100%)
IF POU_V.Vl_16>0.999 OR POU_V.Vl_17>0.999 OR POU_V.Vl_18>0.999 OR POU_V.Vl_19>0.999 OR POU_V.Vl_20>0.999 OR POU_V.Vl_21>0.999 OR POU_V.Vl_22>0.999 THEN Vl_air_otm:=TRUE; ELSE Vl_air_otm:=FALSE; END_IF



//Установка текста сообщения на главном экране
n:=0; IF Dym=FALSE AND Vent=FALSE THEN n:=n+1; Main_W[n]:= "Печь выключена";  Text_W[n]:= " Что можно сказать о выключенной печи? В ней не горит газ, не подается воздух, не поступает руда.... Она просто медленно остывает... Бесполезная вещь... А могла бы работать!"; ELSE//В пределах/печь выключена
      IF B_GOR= TRUE THEN n:=n+1; Main_W[n]:= "Работа печи без подачи газа";  Text_W[n]:= "     В настоящее время похоже, что печь работает с выключенной горелкой. Если это осознанное решение и оно согласовано с руководством, то можно продолжать работать. Однако следует помнить, что длительная работа печи без нагрева, особенно в зимнее время, может привести к следующим негативным последствиям: $R$N   - выход руды из печи с повышенной влажностью, что резко снизит настроение работников цеха обогащения; $R$N   - выход из строя электрофильтра; $R$N   - образование конденсата в дымовой трубе; $R$N   - забив циклонов ввиду повышенной влажности чернового концентрата. $R$N     Поэтому к такому режиму надо подходить со всей ответственностью, проявить повышенной внимание и при необходимости все-таки разжечь печь."; END_IF//Влажность руды не в пределах
      IF No_Rud=TRUE THEN n:=n+1; Main_W[n]:=No_Rud_w;  Text_W[n]:= NO_Rud_w1; END_IF//Работа без загрузки
      IF B_VL=  TRUE AND No_Rud=FALSE AND Pitat=TRUE THEN n:=n+1; Main_W[n]:=VL_w;  Text_W[n]:= VL_w_1; END_IF//Влажность руды не в пределах
      IF B_VL1= TRUE AND No_Rud=FALSE AND Pitat=TRUE THEN n:=n+1; Main_W[n]:=VL_w;  Text_W[n]:= VL_w_1; END_IF//Влажность руды не в пределах
      IF B_D2=  TRUE THEN n:=n+1; Main_W[n]:=D2_w;  Text_W[n]:= D2_w_1; END_IF//Давление перед горелкой не в пределах
      IF B_D9=  TRUE THEN n:=n+1; Main_W[n]:=D9_w;  Text_W[n]:= D9_w_1; END_IF//Разряжение в топке не в пределах
      IF B_T13= TRUE THEN n:=n+1; Main_W[n]:=T13_w; Text_W[n]:= T13_w_1; END_IF//Температура в топке не в пределах
      IF B_D3=  TRUE THEN n:=n+1; Main_W[n]:=D3_w;  Text_W[n]:= D3_w_1; END_IF//Давление воздуха в коллекторе не в пределах
      IF B_D6=  TRUE THEN n:=n+1; Main_W[n]:=D6_w;  Text_W[n]:= D6_w_1; END_IF//Разряжение перед дымососм не в пределах
      IF B_PIT= TRUE THEN n:=n+1; Main_W[n]:=PIT_w; Text_W[n]:= PIT_w_1; END_IF//Загрузка питателя не в пределах
	  IF n=0 THEN  n:=n+1; Main_W[n]:= "Все параметры в пределах уставок"; Text_W[n]:= "   Отличная работа! Если уставки выставлены правильно, то параметры работы печи находятся в границах этих уставок. Вы замечательный работник, отличный специалист и просто хороший человек!"; END_IF; END_IF//В пределах

// Установка флага работы печи с выключенной горелкой с загрузкой
IF (Dym=TRUE OR Vent=TRUE) AND PIT>0.01 AND NO_RUD=FALSE AND gor=FALSE THEN B_GOR:=TRUE;ELSE B_GOR:=FALSE; END_IF

// Установка флага работы печи с горелкой без загрузки
IF No_Rud=TRUE THEN No_Rud_w:= "Руда в печь не поступает"; Vl_color:= 16#FFAAFFD5; Vl_n:=FALSE;
	No_rud_w1:= "     В настоящее время печь работает, но руда в неё не поступает. Это может быть связано с выключением питателя, забивом течки, опустошением бункера. Длительная работа печи без загрузки ведет к резкому увеличению температуры в шахте, нерациональному использованию энергоресурсов, что в конечном итоге может вызвать гнев начальства!$R$N     Рекомендуется в кратчайшие сроки выяснить причину работы печи без загрузки и либо подать в неё руду, либо остановить печь.$R$N    PS. Режим работы печи без загрузки записывается в истории работы печи, поэтому прошу отнестись к этому со всей ответственностью!";END_IF

// Установка флага влажности руды на выходе и текста сообщения
UVl_up_1:=UVl_up-(UVl_up-UVl_dwn)*0.2; UVl_dwn_1:=UVl_dwn+(UVl_up-UVl_dwn)*0.2;

IF (Dym=TRUE OR Vent=TRUE) AND PIT>0.01 AND NO_RUD=FALSE AND B_GOR=FALSE AND POU_V.Vl_rud_out/100>UVl_up THEN B_VL:=TRUE; B_VL1:=FALSE; Vl_n:=FALSE; Vl_color:= 16#FFFF0000;
	IF Vl_air_otm=TRUE THEN  VL_w_1:= "     Согласно показаний датчиков влажность руды на выходе из печи выше уставки, что резко снижает извлекаемость асбеста и настроение работников цеха обогащения! Это может быть связано с подачей более влажной руды на вход, появление снега и льда в руде (в зимнее время) или недавнего изменения режима работы печи.$R$N     Если печь работала в установившемся режиме более 20 минут, необходимо визуально убедиться в том, что руда действительно идет с повышенной влажностью, после чего можно в первую очередь выполнить одно из следующих действий:
$R$N  - увеличить разряжение дымососа на 100-200 Па;$R$N  - увеличить давление после вентилятора на 100-200 Па.$R$N      Если предыдущие способы не подходят, можно:
$R$N  - увеличить давление газа перед горелкой на 100-200 Па (повысить расход газа);$R$N  - уменьшить загрузку питателя на 5-10%.$R$N;     После выполнения вышеуказанных действий необходимо выдержать временной интервал 10-20 минут и убедиться, что влажность руды снизилась до регламентированных значений.$R$N     Если есть уверенность, что расчетная влажность руды не соответствует действительной, необходимо запустить процедуру автокоррекции раcчетной влажности кнопкой `Автокоррекция` на главном экране.";
								VL_w:= WCONCAT(WCONCAT(WCONCAT(WCONCAT("Влажность руды ",REAL_TO_WSTRING(OSCAT_BASIC.ROUND(POU_V.Vl_rud_out, 2))),"% выше уставки "),REAL_TO_WSTRING (UVl_up*100)),"%. Увеличте давление дымосоcа или вентилятора!");
	ELSE 						VL_w_1:= "     Согласно показаний датчиков влажность руды на выходе из печи выше уставки, что резко снижает извлекаемость асбеста и настроение работников цеха обогащения! Это может быть связано с подачей более влажной руды на вход, появление снега и льда в руде (в зимнее время) или недавнего изменения режима работы печи.$R$N     Если печь работала в установившемся режиме более 20 минут, необходимо визуально убедиться в том, что руда действительно идет с повышенной влажностью, после чего можно в первую очередь выполнить одно из следующих действий:
$R$N  - увеличить давление газа перед горелкой на 100-200 Па (повысить расход газа);$R$N  - уменьшить загрузку питателя на 5-10%.$R$N      Если предыдущие способы не подходят, можно:
$R$N  - увеличить разряжение дымососа на 100-200 Па;$R$N  - увеличить давление после вентилятора на 100-200 Па.$R$N     После выполнения вышеуказанных действий необходимо выдержать временной интервал 10-20 минут и убедиться, что влажность руды снизилась до регламентированных значений.$R$N     Если есть уверенность, что расчетная влажность руды не соответствует действительной, необходимо запустить процедуру автокоррекции раcчетной влажности кнопкой `Автокоррекция` на главном экране.";
								VL_w:= WCONCAT(WCONCAT(WCONCAT(WCONCAT("Влажность руды ",REAL_TO_WSTRING(OSCAT_BASIC.ROUND(POU_V.Vl_rud_out, 2))),"% выше уставки "),REAL_TO_WSTRING (UVl_up*100)),"%. Увеличьте давление газа или снизьте загрузку питателя!");
	END_IF
ELSIF (Dym=TRUE OR Vent=TRUE) AND PIT>0.01 AND NO_RUD=FALSE AND B_GOR=FALSE AND Vl_n=TRUE AND POU_V.Vl_rud_out/100>=UVl_up_1 AND POU_V.Vl_rud_out/100<UVl_up THEN B_VL1:=TRUE; B_VL:=FALSE; Vl_color:= 16#FFFFFF00;
VL_w:= WCONCAT(WCONCAT(WCONCAT(WCONCAT("Влажность руды на выходе ",REAL_TO_WSTRING(OSCAT_BASIC.ROUND(POU_V.Vl_rud_out, 2))),"% приближается к верхней границе уставки "),REAL_TO_WSTRING (UVl_up*100)),"%");
	IF Vl_air_otm=TRUE THEN  VL_w_1:= "     Согласно показаний датчиков влажность руды на выходе из печи приближается к верхней границе! Это может быть связано с подачей более влажной руды на вход, появление снега и льда в руде (в зимнее время) или недавнего изменения режима работы печи.
     Нужно проанализировать историю изменения влажности и в случае необходимости можно в первую очередь выполнить одно из следующих действий:
  - увеличить разряжение дымососа на 50-100 Па;$R$N  - увеличить давление после вентилятора на 50-100 Па.$R$N      Если предыдущие способы не подходят, можно:
  - увеличить давление газа перед горелкой на 50-100 Па (повысить расход газа);$R$N  - уменьшить загрузку питателя на 5-10%.$R$N     Если есть уверенность, что расчетная влажность руды не соответствует действительной, необходимо запустить процедуру автокоррекции раcчетной влажности кнопкой `Автокоррекция` на главном экране.";
	ELSE						VL_w_1:= "     Согласно показаний датчиков влажность руды на выходе из печи приближается к верхней границе! Это может быть связано с подачей более влажной руды на вход, появление снега и льда в руде (в зимнее время) или недавнего изменения режима работы печи.
     Нужно проанализировать историю изменения влажности и в случае необходимости можно в первую очередь выполнить одно из следующих действий:
  - увеличить давление газа перед горелкой на 50-100 Па (повысить расход газа);$R$N  - уменьшить загрузку питателя на 5-10%.$R$N      Если предыдущие способы не подходят, можно:
  - увеличить разряжение дымососа на 50-100 Па;$R$N  - увеличить давление после вентилятора на 50-100 Па.$R$N     Если есть уверенность, что расчетная влажность руды не соответствует действительной, необходимо запустить процедуру автокоррекции раcчетной влажности кнопкой `Автокоррекция` на главном экране.";
	END_IF 
ELSIF (Dym=TRUE OR Vent=TRUE) AND PIT>0.01 AND NO_RUD=FALSE AND B_GOR=FALSE AND POU_V.Vl_rud_out/100<UVl_dwn THEN B_VL:=TRUE; B_VL1:=FALSE; Vl_n:=FALSE; Vl_color:= 16#FFFF0000;
	IF Vl_air_otm=TRUE THEN  VL_w_1:= "     Согласно показаний датчиков влажность руды на выходе из печи ниже уставки, что снижает КПД печи и приводит к увеличенному расходу газа и электроэнергии! Это может быть связано с подачей более сухой руды на вход или недавнего изменения режима работы печи.
     Если печь работала в установившемся режиме более 20 минут, необходимо визуально убедиться в том, что руда действительно идет с пониженной влажностью, после чего можно в первую очередь выполнить одно из следующих действий:
  - снизить давление газа перед горелкой на 100-200 Па (уменьшить расход газа);$R$N  - увеличить загрузку питателя на 5-10%.$R$N      Если предыдущие способы не подходят, можно:
  - снизить разряжение дымососа на 100-200 Па;$R$N  - снизить давление после вентилятора на 100-200 Па.$R$N     После выполнения вышеуказанных действий необходимо выдержать временной интервал 10-20 минут и убедиться, что влажность руды увеличилась до регламентированных значений.$R$N     Если есть уверенность, что расчетная влажность руды не соответствует действительной, необходимо запустить процедуру автокоррекции раcчетной влажности кнопкой `Автокоррекция` на главном экране.";
								VL_w:= WCONCAT(WCONCAT(WCONCAT(WCONCAT("Влажность руды ",REAL_TO_WSTRING(OSCAT_BASIC.ROUND(POU_V.Vl_rud_out, 2))),"% ниже уставки "),REAL_TO_WSTRING (UVl_dwn*100)),"%. Снизьте расход газа или увеличьте загрузку питателя!");
	ELSE						VL_w_1:= "     Согласно показаний датчиков влажность руды на выходе из печи ниже уставки, что снижает КПД печи и приводит к увеличенному расходу газа и электроэнергии! Это может быть связано с подачей более сухой руды на вход или недавнего изменения режима работы печи.
     Если печь работала в установившемся режиме более 20 минут, необходимо визуально убедиться в том, что руда действительно идет с пониженной влажностью, после чего можно в первую очередь выполнить одно из следующих действий:
  - снизить разряжение дымососа на 100-200 Па;$R$N  - снизить давление после вентилятора на 100-200 Па.$R$N      Если предыдущие способы не подходят, можно:
  - снизить давление газа перед горелкой на 100-200 Па (уменьшить расход газа);$R$N  - увеличить загрузку питателя на 5-10%.$R$N     После выполнения вышеуказанных действий необходимо выдержать временной интервал 10-20 минут и убедиться, что влажность руды увеличилась до регламентированных значений.$R$N     Если есть уверенность, что расчетная влажность руды не соответствует действительной, необходимо запустить процедуру автокоррекции раcчетной влажности кнопкой `Автокоррекция` на главном экране.";
								VL_w:= WCONCAT(WCONCAT(WCONCAT(WCONCAT("Влажность руды ",REAL_TO_WSTRING(OSCAT_BASIC.ROUND(POU_V.Vl_rud_out, 2))),"% ниже уставки "),REAL_TO_WSTRING (UVl_dwn*100)),"%. Снизьте давление дымосоcа или вентилятора!");
END_IF
ELSIF (Dym=TRUE OR Vent=TRUE) AND PIT>0.01 AND NO_RUD=FALSE AND B_GOR=FALSE AND Vl_n=TRUE AND POU_V.Vl_rud_out/100<=UVl_dwn_1 AND POU_V.Vl_rud_out/100>UVl_dwn THEN B_VL1:=TRUE; B_VL:=FALSE; Vl_color:= 16#FFFFFF00;
VL_w:= WCONCAT(WCONCAT(WCONCAT(WCONCAT("Влажность руды на выходе ",REAL_TO_WSTRING(OSCAT_BASIC.ROUND(POU_V.Vl_rud_out, 2))),"% приближается к нижней границе уставки "),REAL_TO_WSTRING (UVl_dwn*100)),"%");
	IF Vl_air_otm=TRUE THEN  VL_w_1:= "     Согласно показаний датчиков влажность руды на выходе из печи приближается к нижней границе! Это может быть связано с подачей более сухой руды на вход или недавнего изменения режима работы печи.
     Нужно проанализировать историю изменения влажности и в случае необходимости можно в первую очередь выполнить одно из следующих действий:
  - снизить давление газа перед горелкой на 50-100 Па (уменьшить расход газа);$R$N  - увеличить загрузку питателя на 5-10%.$R$N      Если предыдущие способы не подходят, можно:
  - снизить разряжение дымососа на 50-100 Па;$R$N  - снизить давление после вентилятора на 50-100 Па.$R$N     После выполнения вышеуказанных действий необходимо выдержать временной интервал 10-20 минут и убедиться, что влажность руды увеличилась до регламентированных значений.$R$N     Если есть уверенность, что расчетная влажность руды не соответствует действительной, необходимо запустить процедуру автокоррекции раcчетной влажности кнопкой `Автокоррекция` на главном экране.";
	ELSE						VL_w_1:= "     Согласно показаний датчиков влажность руды на выходе из печи приближается к нижней границе! Это может быть связано с подачей более сухой руды на вход или недавнего изменения режима работы печи.
     Нужно проанализировать историю изменения влажности и в случае необходимости можно в первую очередь выполнить одно из следующих действий:
  - снизить разряжение дымососа на 50-100 Па;$R$N  - снизить давление после вентилятора на 50-100 Па.$R$N      Если предыдущие способы не подходят, можно:
  - снизить давление газа перед горелкой на 50-100 Па (уменьшить расход газа);$R$N  - увеличить загрузку питателя на 5-10%.$R$N     После выполнения вышеуказанных действий необходимо выдержать временной интервал 10-20 минут и убедиться, что влажность руды увеличилась до регламентированных значений.$R$N     Если есть уверенность, что расчетная влажность руды не соответствует действительной, необходимо запустить процедуру автокоррекции раcчетной влажности кнопкой `Автокоррекция` на главном экране.";
END_IF
ELSIF (Dym=TRUE OR Vent=TRUE) AND POU_V.Vl_rud_out/100>=UVl_dwn_1 AND POU_V.Vl_rud_out/100<=UVl_up_1 THEN B_VL:=FALSE; B_VL1:=FALSE; Vl_n:=TRUE; Vl_color:= 16#FFAAFFD5;
ELSIF (Dym=TRUE OR Vent=TRUE) AND Vl_n=FALSE AND POU_V.Vl_rud_out/100>=UVl_dwn AND POU_V.Vl_rud_out/100<=UVl_up THEN B_VL:=FALSE; B_VL1:=FALSE; Vl_color:= 16#FFAAFFD5;
ELSIF (Dym=FALSE AND Vent=FALSE) OR NO_RUD=TRUE OR B_GOR=TRUE THEN B_VL:=FALSE; B_VL1:=FALSE; Vl_color:= 16#FFAAFFD5;
END_IF


IF (Dym=TRUE OR Vent=TRUE) THEN
// Установка флага давления газа на горелку и текста сообщения")
IF D2>UD2_up THEN B_D2:=TRUE; D2_w:= WCONCAT(WCONCAT(WCONCAT(WCONCAT("Давление газа перед горелкой ",REAL_TO_WSTRING(D2)),"Па выше уставки "),REAL_TO_WSTRING (UD2_up)),"Па");
	D2_w_1:= "   Повышенное давление газа может стать причиной серьёзной аварии. Рекомендуется проверить давление газа по показывающему прибору и при необходимости отрегулировать его. Если есть уверенность, что данный параметр в норме, можно изменить уставку на экране уставок (`Подробнее` -> `Уставки`).";
ELSIF D2<UD2_dwn AND B_GOR=FALSE THEN B_D2:=TRUE; D2_w:= WCONCAT(WCONCAT(WCONCAT(WCONCAT("Давление газа перед горелкой ",REAL_TO_WSTRING(D2)),"Па ниже уставки "),REAL_TO_WSTRING (UD2_dwn)),"Па");
	D2_w_1:= "   Пониженное давление газа может стать причиной серьёзной аварии. Рекомендуется проверить давление газа по показывающему прибору и при необходимости отрегулировать его. Если есть уверенность, что данный параметр в норме, можно изменить уставку на экране уставок (`Подробнее` -> `Уставки`).";
ELSE B_D2:=FALSE; D2_w :=  "Давление перед горелкой в пределах уставок максимального и минимального значения"; END_IF

// Установка флага разряжения в топке и текста сообщения")
IF D9<UD9_up THEN B_D9:=TRUE; D9_w:= WCONCAT(WCONCAT(WCONCAT(WCONCAT("Разряжение в топке ",REAL_TO_WSTRING(D9)),"Па выше уставки "),REAL_TO_WSTRING (UD9_up)),"Па");
	D9_w_1:= "   Надо ответить на простой вопрос: действительно ли необходимо поддерживать такое разряжение? Возможен срыв факела в топке! Ну и кирпичи начнут осыпаться вовнутрь, что тоже не хорошо! Рекомендуется проверить разряжение по показывающему прибору и при необходимости отрегулировать его. Если есть уверенность, что данный параметр в норме, можно изменить уставку на экране уставок (`Подробнее` -> `Уставки`).";
ELSIF D9>UD9_dwn THEN B_D9:=TRUE; D9_w:= WCONCAT(WCONCAT(WCONCAT(WCONCAT("Разряжение в топке ",REAL_TO_WSTRING(D9)),"Па ниже уставки "),REAL_TO_WSTRING (UD9_dwn)),"Па");
	D9_w_1:= "   Это очень серьёзно, такое разряжение может привести к загазованности корпуса сушки, придутся дышать дымовыми газами. Вообще должна была сработать аварийная автоматика, а печь отсечься по газу. В любом случае, НАСТОЯТЕЛЬНО рекомендуется проверить разряжение по показывающему прибору и при необходимости отрегулировать его. Если есть уверенность, что данный параметр в норме, можно изменить уставку на экране уставок (`Подробнее` -> `Уставки`).";
ELSE B_D9:=FALSE; D9_w :=  "Разряжение в топке в пределах уставок максимального и минимального значения"; END_IF

// Установка флага температуры топки и текста сообщения")
IF T13>UT13_up THEN B_T13:=TRUE; T13_w:= WCONCAT(WCONCAT(WCONCAT(WCONCAT("Температура в топке ",REAL_TO_WSTRING(T13)),"°C выше уставки "),REAL_TO_WSTRING (UT13_up)),"°C");
	T13_w_1:= "   Причиной такой высокой температуры может быть повышенный расход газа, слишком низкое разряжение в топке или низкое давление после вентилятора. Надо все как следует посмотреть и при необходимости поправить! Если есть уверенность, что данный параметр в норме, можно изменить уставку на экране уставок (`Подробнее` -> `Уставки`).";
ELSIF T13<UT13_dwn AND B_GOR=FALSE THEN B_T13:=TRUE; T13_w:= WCONCAT(WCONCAT(WCONCAT(WCONCAT("Температура в топке ",REAL_TO_WSTRING(T13)),"°C ниже уставки "),REAL_TO_WSTRING (UT13_dwn)),"°C");
	T13_w_1:= "   Причиной такой низкой температуры может быть слишком маленький расход газа, очень большое разряжение в топке или повышенное давление после вентилятора. Надо все как следует посмотреть и при необходимости поправить! Если есть уверенность, что данный параметр в норме, можно изменить уставку на экране уставок (`Подробнее` -> `Уставки`).";
ELSE B_T13:=FALSE; T13_w :=  "Температура в топке в пределах уставок максимального и минимального значения"; END_IF

// Установка флага давления воздуха в коллекторе и текста сообщения")
IF D3>UD3_up THEN B_D3:=TRUE; D3_w:= WCONCAT(WCONCAT(WCONCAT(WCONCAT("Давление воздуха в коллекторе ",REAL_TO_WSTRING(D3)),"Па выше уставки "),REAL_TO_WSTRING (UD3_up)),"Па");
	D3_w_1:= "   Вентилятор работает в максимальном режиме! Возможны перегрев двигателя, а так же срыв факела. Если необходимости в таком давлении нет, его надо снизить! Если есть уверенность, что данный параметр в норме, можно изменить уставку на экране уставок (`Подробнее` -> `Уставки`).";
ELSIF D3<UD3_dwn THEN B_D3:=TRUE; D3_w:= WCONCAT(WCONCAT(WCONCAT(WCONCAT("Давление воздуха в коллекторе ",REAL_TO_WSTRING(D3)),"Па ниже уставки "),REAL_TO_WSTRING (UD3_dwn)),"Па");
	D3_w_1:= "   Что-то вентилятор расслабился и дует ниже минимальной уставки! Рекомендуется проверить давление в коллекторе по показывающему прибору и при необходимости отрегулировать его. Если есть уверенность, что данный параметр в норме, можно изменить уставку на экране уставок (`Подробнее` -> `Уставки`).";
ELSE B_D3:=FALSE; D3_w :=  "Давление воздуха в коллекторе в пределах уставок максимального и минимального значения"; END_IF

// Установка флага разряжения дымососа и текста сообщения")
IF D6<UD6_up THEN B_D6:=TRUE; D6_w:= WCONCAT(WCONCAT(WCONCAT(WCONCAT("Разряжение дымососа ",REAL_TO_WSTRING(D6)),"Па выше уставки "),REAL_TO_WSTRING (UD6_up)),"Па");
	D6_w_1:= "   Дымосос работает в максимальном режиме! Возможны перегрев двигателя, а так повышенный расход электроэнергии. Если необходимости в таком разряжении нет, его надо снизить! Если есть уверенность, что данный параметр в норме, можно изменить уставку на экране уставок (`Подробнее` -> `Уставки`).";
ELSIF D6>UD6_dwn THEN B_D6:=TRUE; D6_w:= WCONCAT(WCONCAT(WCONCAT(WCONCAT("Разряжение дымососа ",REAL_TO_WSTRING(D6)),"Па ниже уставки "),REAL_TO_WSTRING (UD6_dwn)),"Па");
	D6_w_1:= "   Такое низкое разряжение дымососа может привести к пониженному разряжению в топке, что очень опасно. Необходимо проконтролировать текущее разряжение в топке. Если разряжение в топке нормальное и соответствует текущему режиму работы печи, то напрягать дымосос не слудет. Для исчезновения данного сообщения можно изменить уставку на экране уставок (`Подробнее` -> `Уставки`).";
ELSE B_D6:=FALSE; D6_w :=  "Разряжения дымососа в пределах уставок максимального и минимального значения"; END_IF

// Установка флага загрузки питателя и текста сообщения")
IF Pit>UPit_up THEN B_Pit:=TRUE; Pit_w:= WCONCAT(WCONCAT(WCONCAT(WCONCAT("Загрузка питателя ",REAL_TO_WSTRING(Pit)),"% выше уставки "),REAL_TO_WSTRING (UPit_up*100)),"%");
	Pit_w_1:= "   Кто-то зачем-то выставил такую уставку, и текущая загрузка питателя выше уставки. Надо бы подумать, кому это надо было... Ну и если ничего в голову не пришло - просто увеличить уставку. Ну или все-таки снизить загрузку питателя";
ELSIF Pit<UPit_dwn THEN B_Pit:=TRUE; Pit_w:= WCONCAT(WCONCAT(WCONCAT(WCONCAT("Загрузка питателя ",REAL_TO_WSTRING(Pit)),"% ниже уставки "),REAL_TO_WSTRING (UPit_dwn*100)),"%");
	Pit_w_1:= "   Работа на такой низкой загрузке без веской на то причины приводит к низкому КПД печи, недоотпуску продукции, необходимости разжигать дополнительные печи! Если веской причины нет, загрузку печи можно увеличить! Если есть уверенность, что данный параметр в норме, можно изменить уставку на экране уставок (`Подробнее` -> `Уставки`).";
ELSE B_Pit:=FALSE; Pit_w :=  "Загрузка питателя в пределах уставок максимального и минимального значения"; END_IF
END_IF


IF (Dym=FALSE AND Vent=FALSE) THEN B_D2:=FALSE; D2_w:= "(печь выключена)"; B_D9:=FALSE; D9_w:= "Давление газа перед горелкой (печь выключена)"; B_T13:=FALSE; T13_w:= "(печь выключена)"; B_D3:=FALSE; D3_w:= "(печь выключена)"; B_D6:=FALSE; D6_w:= "(печь выключена)"; B_Pit:=FALSE; Pit_w:= "(печь выключена)"; END_IF

Timer (IN := TRUE, PT:= T#20S);
IF Timer.Q THEN

	// Проверка роста температуры в топке ТХА
IF T13_Stab=0 AND PLC_PRG.T13<>0 THEN T13_Stab:=PLC_PRG.T13; END_IF
IF PLC_PRG.T13>0 AND T13_Stab<>0 THEN IF ABS(1-Prev_2_T13/PLC_PRG.T13)<0.005 AND ABS(1-Prev_1_T13/PLC_PRG.T13)<0.005 AND PLC_PRG.T13/T13_Stab>1.02 THEN UP_T13:=TRUE; T13_Stab:=PLC_PRG.T13; END_IF END_IF
IF PLC_PRG.T13>0 AND T13_Stab<>0 THEN IF ABS(1-Prev_2_T13/PLC_PRG.T13)<0.005 AND ABS(1-Prev_1_T13/PLC_PRG.T13)<0.005 AND PLC_PRG.T13/T13_Stab<0.98 THEN DWN_T13 :=TRUE;  T13_Stab:=PLC_PRG.T13; END_IF END_IF
    Prev_2_T13 := Prev_1_T13;
    Prev_1_T13 := PLC_PRG.T13;

	// Проверка роста температуры в топке ТХА
IF T14_Stab=0 AND PLC_PRG.T14<>0 THEN T14_Stab:=PLC_PRG.T14; END_IF
IF PLC_PRG.T14>0 AND T14_Stab<>0 THEN IF ABS(1-Prev_2_T14/PLC_PRG.T14)<0.005 AND ABS(1-Prev_1_T14/PLC_PRG.T14)<0.005 AND PLC_PRG.T14/T14_Stab>1.02 THEN UP_T14:=TRUE; T14_Stab:=PLC_PRG.T14; END_IF END_IF
IF PLC_PRG.T14>0 AND T14_Stab<>0 THEN IF ABS(1-Prev_2_T14/PLC_PRG.T14)<0.005 AND ABS(1-Prev_1_T14/PLC_PRG.T14)<0.005 AND PLC_PRG.T14/T14_Stab<0.98 THEN DWN_T14 :=TRUE;  T14_Stab:=PLC_PRG.T14; END_IF END_IF
    Prev_2_T14 := Prev_1_T14;
    Prev_1_T14 := PLC_PRG.T14;

	// Проверка роста давления газа на горелку
IF D2_Stab=0 AND PLC_PRG.D2<>0 THEN D2_Stab:=PLC_PRG.D2; END_IF
IF PLC_PRG.D2>0 AND D2_Stab<>0 THEN IF ABS(1-Prev_2_D2/PLC_PRG.D2)<0.01 AND ABS(1-Prev_1_D2/PLC_PRG.D2)<0.01 AND PLC_PRG.D2/D2_Stab>1.04 THEN UP_D2:=TRUE; D2_Stab:=PLC_PRG.D2; END_IF END_IF
IF PLC_PRG.D2>0 AND D2_Stab<>0 THEN IF ABS(1-Prev_2_D2/PLC_PRG.D2)<0.01 AND ABS(1-Prev_1_D2/PLC_PRG.D2)<0.01 AND PLC_PRG.D2/D2_Stab<0.96 THEN DWN_D2 :=TRUE;  D2_Stab:=PLC_PRG.D2; END_IF END_IF
    Prev_2_D2 := Prev_1_D2;
    Prev_1_D2 := PLC_PRG.D2;

	// Проверка роста давления после вентилятора
IF D5_Stab=0 AND PLC_PRG.D5<>0 THEN D5_Stab:=PLC_PRG.D5; END_IF
IF PLC_PRG.D5>0 AND D5_Stab<>0 THEN IF ABS(1-Prev_2_D5/PLC_PRG.D5)<0.005 AND ABS(1-Prev_1_D5/PLC_PRG.D5)<0.005 AND PLC_PRG.D5/D5_Stab>1.02 THEN UP_D5:=TRUE; D5_Stab:=PLC_PRG.D5; END_IF END_IF
IF PLC_PRG.D5>0 AND D5_Stab<>0 THEN IF ABS(1-Prev_2_D5/PLC_PRG.D5)<0.005 AND ABS(1-Prev_1_D5/PLC_PRG.D5)<0.005 AND PLC_PRG.D5/D5_Stab<0.98 THEN DWN_D5 :=TRUE;  D5_Stab:=PLC_PRG.D5; END_IF END_IF
    Prev_2_D5 := Prev_1_D5;
    Prev_1_D5 := PLC_PRG.D5;

	// Проверка роста разряжения после дымососа
IF D6_Stab=0 AND PLC_PRG.D6<>0 THEN D6_Stab:=PLC_PRG.D6; END_IF
IF PLC_PRG.D6>0 AND D6_Stab<>0 THEN IF ABS(1-Prev_2_D6/PLC_PRG.D6)<0.005 AND ABS(1-Prev_1_D6/PLC_PRG.D6)<0.005 AND PLC_PRG.D6/D6_Stab>1.02 THEN UP_D6:=TRUE; D6_Stab:=PLC_PRG.D6; END_IF END_IF
IF PLC_PRG.D6>0 AND D6_Stab<>0 THEN IF ABS(1-Prev_2_D6/PLC_PRG.D6)<0.005 AND ABS(1-Prev_1_D6/PLC_PRG.D6)<0.005 AND PLC_PRG.D6/D6_Stab<0.98 THEN DWN_D6 :=TRUE;  D6_Stab:=PLC_PRG.D6; END_IF END_IF
    Prev_2_D6 := Prev_1_D6;
    Prev_1_D6 := PLC_PRG.D6;

	// Проверка изменения загрузки питателя
IF PIT_Stab=0 AND PLC_PRG.PIT>0 THEN PIT_Stab:=PLC_PRG.PIT; END_IF
IF PLC_PRG.PIT>0 AND PIT_Stab>0 THEN IF ABS(1-Prev_2_PIT/PLC_PRG.PIT)<0.005 AND ABS(1-Prev_1_PIT/PLC_PRG.PIT)<0.005 AND PLC_PRG.PIT/PIT_Stab>1.02 THEN UP_PIT:=TRUE; PIT_Stab:=PLC_PRG.PIT; END_IF END_IF
IF PLC_PRG.PIT>0 AND PIT_Stab>0 THEN IF ABS(1-Prev_2_PIT/PLC_PRG.PIT)<0.005 AND ABS(1-Prev_1_PIT/PLC_PRG.PIT)<0.005 AND PLC_PRG.PIT/PIT_Stab<0.98 THEN DWN_PIT :=TRUE;  PIT_Stab:=PLC_PRG.PIT; END_IF END_IF
    Prev_2_PIT := Prev_1_PIT;
    Prev_1_PIT := PLC_PRG.PIT;

	// Проверка изменения расхода газа
