  IF V7>80000 THEN V7:= 80000; ELSIF V7<1 THEN V7:=1; END_IF
  IF V8>20000 THEN V8:= 20000; ELSIF V8<1 THEN V8:=1; END_IF
  IF V8_1>10000 THEN V8_1:= 20000; ELSIF V8_1<1 THEN V8_1:=1; END_IF
  IF V8_2>20000 THEN V8_2:= 20000; ELSIF V8_2<1 THEN V8_2:=1; END_IF
  IF V8_3>20000 THEN V8_3:= 20000; ELSIF V8_3<1 THEN V8_3:=1; END_IF
  IF V8_4>20000 THEN V8_4:= 20000; ELSIF V8_4<0.001 THEN V8_4:=0.001; END_IF
  IF V8_1P>1 THEN V8_1P:=1; ELSIF V8_1P<0 THEN V8_1P:=0; END_IF
  IF V8_2P>1 THEN V8_2P:= 1; ELSIF V8_2P<0 THEN V8_2P:=0; END_IF
  IF V8_3P>1 THEN V8_3P:= 1; ELSIF V8_3P<0 THEN V8_3P:=0; END_IF
  IF V8_4P>1 THEN V8_4P:= 1; ELSIF V8_4P<0 THEN V8_4P:=0; END_IF
  IF Vtop_1P>0.5 THEN Vtop_1P:= 0.5; ELSIF Vtop_1P<0 THEN Vtop_1P:=0; END_IF
  IF Vtop_2P>0.3 THEN Vtop_2P:= 0.3; ELSIF Vtop_2P<0 THEN Vtop_2P:=0; END_IF
  IF Vtop_3P>1 THEN Vtop_3P:= 1; ELSIF Vtop_3P<0 THEN Vtop_3P:=0; END_IF
//---//

//Автонастройка коэффициентов расхода и испарения
IF DIFF.ON=FALSE THEN AUTO_Start:=FALSE; END_IF
IF AUTO_St AND AUTO_Start=FALSE AND DIFF.Stab THEN Auto:=TRUE; AUTO_Start:=TRUE; END_IF

//Настройка через коэффициент времени k_t_air
//IF Auto AND EN1 THEN ; IF VL_Auto=0 THEN VL_Auto:=0.1; END_IF IF T3+T4=0 THEN T3:=T3+0.1; END_IF  
//		IF (VL_rud_5*100/VL_Auto>0 AND T_22/((T3+T4)/2)>0) OR (VL_rud_5*100/VL_Auto<0 AND T_22/((T3+T4)/2)<0) THEN k_t_air:=k_t_air-(1-VL_rud_5*100/VL_Auto)*0.01-(1-T_22/((T3+T4)/2))*0.2;
//		ELSE k_t_air:=k_t_air-(1-VL_rud_5/(VL_Auto/100))*0.01; END_IF	
//		IF k_t_air<0.5 THEN k_t_air:=0.5; ELSIF k_t_air>=1.5 THEN k_t_air:=1.5; END_IF
//  	IF VL_rud_5*100-VL_Auto<-0.05*k_Auto OR VL_rud_5*100-VL_Auto>0.05*k_Auto THEN Timer_Auto(IN := FALSE);k_Auto:=1;
//	ELSE Timer_Auto (IN := TRUE, PT:= T#30S); k_Auto:=1.5;
//		IF Timer_Auto.Q AND VL_rud_5*100-VL_Auto<0.15 AND VL_rud_5*100-VL_Auto>-0.15 THEN Timer_Auto(IN := FALSE); AUTO:=FALSE; k_Auto:=1; Auto_Scr3:=TRUE; Auto_Scr4:=FALSE; END_IF
// 	END_IF END_IF	

//Настройка через теплоту газа C_g
IF Auto AND EN1 THEN IF VL_Auto=0 THEN VL_Auto:=0.1; END_IF IF T3+T4=0 THEN T3:=T3+0.1; END_IF  
		IF (Vl_rud_out*100/VL_Auto>0 AND T_22/((T3+T4)/2)>0) OR (Vl_rud_out*100/VL_Auto<0 AND T_22/((T3+T4)/2)<0) THEN C_g:=C_g+(1-Vl_rud_out*100/VL_Auto)*10+(1-T_22/(0.5*T3+0.5*T4))*15;
		ELSE C_g:=C_g+(1-Vl_rud_out*100/(VL_Auto))*8; END_IF	
		IF C_g<33000 THEN C_g:=33000; ELSIF C_g>=39000 THEN C_g:=39000; END_IF
  	IF Vl_rud_out*100-VL_Auto<-0.05*k_Auto OR Vl_rud_out*100-VL_Auto>0.05*k_Auto THEN Timer_Auto(IN := FALSE);k_Auto:=1;
	ELSE Timer_Auto (IN := TRUE, PT:= T#30S); k_Auto:=1.5;
		IF Timer_Auto.Q AND Vl_rud_out*100-VL_Auto<0.15 AND Vl_rud_out*100-VL_Auto>-0.15 THEN Timer_Auto(IN := FALSE); AUTO:=FALSE; k_Auto:=1; Auto_Scr3:=TRUE; Auto_Scr4:=FALSE; END_IF
 	END_IF END_IF	



T_fac:= (Q_gaz*C_g+(V2+V3+V4)*FB_p_air(T_air)*FB_c_air(T_air)*T_air+(V2+V3+V4)*VL_air_abs/1000*FB_c_par(T_air)*T_air+V8_1*FB_p_air(T16)*FB_c_air(T_16)*T16+V8_1*VL_air_abs/1000*FB_c_par(T16)*T16)/((V2+V3+V4)*FB_p_air(T_air)*FB_c_air(T_air)+(V2+V3+V4)*VL_air_abs/1000*FB_c_par(T_air)+V8_1*FB_p_air(T16)*FB_c_air(T16)+V8_1*VL_air_abs/1000*FB_c_par(T16));
V_top:= (V2+V3+V4+V8_1)/3600/5.04;
Q_pot_top_in:= k_top_in*1.0846*LREAL_TO_REAL(EXPT(V_top,0.4932))*(50.4*2+32.4)*(T_fac-T_st_top_in)*0.06;
T_top:= T_fac-(Q_pot_top_in*60-(V2+V3+V4+V8_1)*VL_air_abs/1000*(FB_Q_par(T_top)-FB_Q_par(T_fac)))/(((V2+V3+V4)*FB_p_air(T_air)+V8_1*FB_p_air(T16))*FB_c_air(T_top));


//Проверка значений
  IF T_fac>900 THEN T_fac:= 900; ELSIF T_fac<0 THEN T_fac:=0; END_IF
  IF T_top>600 THEN T_top:= 600; ELSIF T_top<-30 THEN T_top:=-30; ELSIF T_top<>T_top THEN T_top:=200;END_IF
  IF Q_pot_top_in>1000000 THEN Q_pot_top_in:= 1000000; ELSIF Q_pot_top_in<-1000000 THEN Q_pot_top_in:=- 1000000; END_IF
  IF V_top>10 THEN V_top:= 10; ELSIF V_top<0.01 THEN V_top:=0.01; END_IF
//---//

IF DIFF.ZAG_OFF=FALSE THEN // Руда поступает
Timer_2(IN:= TRUE, PT := T#60M); 
ELSE Timer_2(IN:= FALSE); END_IF

IF (PLC_PRG.Vent=TRUE AND PLC_PRG.Dym=TRUE AND M_rud>0 AND M_rud_suh>0) OR dat THEN //Печь включена
EN:= TRUE;
k_isp:= 6.7+k_isp_dob;
IF k_isp>10 THEN k_isp:= 10; ELSIF k_isp<0 THEN k_isp:=0; END_IF
k_PIT:=0.95*PIT_1+0.05+k_PIT_dob;

//Расчет коэффициента объема воздуха от температур в топке
IF T14<>0 AND PLC_PRG.B_GOR=FALSE THEN k_V_dif:=((T_top-0)/(0.5*(T13+T14))-1)*0.5; IF k_V_dif>0.1 THEN k_V_dif:=0.1; END_IF IF k_V_dif<-0.1 THEN k_V_dif:=-0.1; END_IF 
k_V:=k_V+k_V_dif;
IF k_V<0.8 THEN k_V:=0.8; ELSIF k_V>1.3 THEN k_v:=1.3; END_IF
ELSE k_V:=1; END_IF

//Расчет влажности на выходе

IF PLC_PRG.B_GOR=FALSE THEN VL_rud_5_dif:=((T_22+T_dob)/((T3+T4)/2)-1)*0.003; IF VL_rud_5_dif>0.002 THEN VL_rud_5_dif:=0.002; END_IF IF VL_rud_5_dif<-0.002 THEN VL_rud_5_dif:=-0.002; END_IF
VL_rud_5:=VL_rud_5+VL_rud_5_dif;
IF VL_rud_5>0.05 THEN VL_rud_5:=0.05; ELSIF VL_rud_5<0.005 THEN VL_rud_5:=0.005; END_IF
Vl_rud_in:=VL_rud_21*100; Vl_rud_out:=((PLC_PRG.UVl_up+PLC_PRG.UVl_dwn)/2+(VL_rud_5-(PLC_PRG.UVl_up+PLC_PRG.UVl_dwn)/2)*0.9)*100;
VL_RUD_OUT_wrd:= WCONCAT(STRING_TO_WSTRING (FB_Format_Number (rValue:=Vl_rud_out, iDecimals:=2)),"%");
VL_RUD_IN_wrd:= WCONCAT(STRING_TO_WSTRING (FB_Format_Number (rValue:=Vl_rud_in, iDecimals:=2)),"%");
ELSE Vl_rud_in:=0; Vl_rud_out:=0; VL_RUD_OUT_wrd:= "---"; VL_RUD_IN_wrd:= "---"; END_IF


//Расчет % байпаса на отм. +21
IF T5<>0 AND PLC_PRG.B_GOR=FALSE THEN Vtop_1P_dif:=(T_12/T5-1)*0.1;  IF Vtop_1P_dif>0.005 THEN Vtop_1P_dif:=0.005; END_IF IF Vtop_1P_dif<-0.005 THEN Vtop_1P_dif:=-0.005; END_IF
Vtop_1P:=Vtop_1P+Vtop_1P_dif;
IF Vtop_1P<0.01 THEN Vtop_1P:=0.01; ELSIF Vtop_1P>0.5 THEN Vtop_1P:=0.5; END_IF
ELSE Vtop_1P:=0.15; END_IF

//Расчет температуры руды на выходе
T_rud_5:=T_rud_5+(T9+T_rud_kor-T_rud_22)*0.1;
IF T_rud_5<-30 THEN T_rud_5:=-30; ELSIF T_rud_5>60 THEN T_rud_5:=60; END_IF

//Расчет % байпаса на отм. +16
k_Vtop_2P:=TIME_TO_REAL (TIMER_2.ET)/3600000;
IF T_16<>0 AND PLC_PRG.B_GOR=FALSE THEN Vtop_2P_dif:= (T6/T_16-1)*0.02; IF Vtop_2P_dif>0.01 THEN Vtop_2P_dif:=0.01; END_IF IF Vtop_2P_dif<-0.01 THEN Vtop_2P_dif:=-0.01; END_IF
Vtop_2P_ist:=Vtop_2P_ist+Vtop_2P_dif;
IF Vtop_2P_ist<0 THEN Vtop_2P_ist:=0; ELSIF Vtop_2P_ist>0.1 THEN Vtop_2P_ist:=0.1; END_IF;
Vtop_2P:= k_Vtop_2P*Vtop_2P_ist;
ELSE Vtop_2P:=0; END_IF		

ELSE EN:= FALSE; //Печь выключена
VL_RUD_OUT_wrd:= "---"; VL_RUD_IN_wrd:= "---"; 
Vl_rud_in:=0; Vl_rud_out:=0; END_IF

IF Q_gaz>0	THEN KPD:= (Q_ISP_5+Q_ISP_6+Q_ISP_7+Q_ISP_8+Q_ISP_9+Q_ISP_10+Q_ISP_11+Q_ISP_12+Q_ISP_13+Q_ISP_14+Q_ISP_15+Q_ISP_16+Q_ISP_17+Q_ISP_18+Q_ISP_19+Q_ISP_20+Q_ISP_21)/Q_gaz/C_g*100; ELSE KPD:=0; END_IF
IF KPD>100 THEN KPD:= 100; ELSIF KPD<0 THEN KPD:=0; END_IF
IF M_rud<>0 THEN UD:=Q_gaz/M_rud*1000; ELSE UD:=0; END_IF
IF UD>1000 THEN UD:= 1000; ELSIF UD<0 THEN UD:=0; END_IF

P_Vent:=0.0000005*V1*D5;	PW_Vent:=REAL_TO_WORD (OSCAT_BASIC.ROUND (P_Vent,0));
P_Dym:=-0.0000005*V7*D6;	PW_Dym:=REAL_TO_WORD (OSCAT_BASIC.ROUND (P_Dym,0));
W_WR:=REAL_TO_WORD (OSCAT_BASIC.ROUND (Vl_rud_out*1000,0)/1000);

IF EN=FALSE OR M_rud=0 OR M_rud_suh=0 OR (DIFF.ZAG_OFF=TRUE AND dat=FALSE) THEN EN1:=FALSE;
ELSE EN1:=TRUE; END_IF

	IF EN=FALSE THEN AUTO_EN:=FALSE; Text_Auto:=  "     В настоящий момент печь выключена, поэтому нет никакого смысла запускать автонастройку! Как можно настроить то, чего нет? Для автонастройки необходимо, чтобы печь работала, причем успела поработать в установившемся режиме как минимум 10 минут. Закройте это окно и не майтесь ерундой!"; 
	ELSIF EN=TRUE AND (M_rud=0 OR M_rud_suh=0) THEN AUTO_EN:=FALSE; Text_Auto:=  "     В настоящий момент руда в печь не поступает, поэтому нет никакого смысла запускать автонастройку! Для автонастройки необходимо, чтобы печь работала, причем успела поработать в установившемся режиме как минимум 10 минут. Кроме того, поступление руды в печь тоже является обязательным условием для автонастройки! Закройте это окно и не майтесь ерундой!"; 
	ELSIF EN=TRUE AND PLC_PRG.B_GOR=TRUE THEN AUTO_EN:=FALSE; Text_Auto:=  "     В настоящий момент печь работает с выключенной горелкой, поэтому нет никакого смысла запускать автонастройку! Для автонастройки необходимо, чтобы печь работала, причем успела поработать в установившемся режиме как минимум 10 минут. Кроме того, горение газа в печи тоже является обязательным условием для автонастройки! Закройте это окно и не майтесь ерундой!"; 
	ELSIF DIFF.Stab=FALSE THEN AUTO_EN:=TRUE; Text_Auto:= "     Сейчас параметры печи нестабильны, видимо недавно был изменен режим её работы. Автонастройка сейчас нежелательна, лучше подождать стабилизации параметров.  Если все-таки есть жгучее желание запустить автонастройку - вперед, но я предупреждал!!!";
	ELSE AUTO_EN:=TRUE; Text_Auto:= "     Данная операция необходима при расхождении расчетной влажности руды на выходе из печи от фактической, определенной визуально или лабораторно.$R$N     Автонастройку коэффициентов следует запускать, если печь проработала в установившемся режиме как минимум 10 минут.$R$N     В автонастройке нет смысла, если недавно был изменен один или несколько следующих параметров:$R$N -  давление вентилятора;$R$N -  разряжение дымососа;$R$N - расход газа;$R$N - загрузка питателя.$R$N     После выполнения процедуры автонастройки можно ориентироваться на показатель расчетной влажности и оперативно вносить изменения в работу печи при отклонении расчетной влажности от требуемой, следуя указаниям на экране."; END_IF 



//Расчет параметра потока на отм. +5 (заходит в шахту)
M_air_top_5:=(V2+V3+V4)*Vtop_3P*FB_p_air(T_air)+V8_1*Vtop_3P*FB_p_air(T16); IF M_air_top_5=0 THEN M_air_top_5:=500; END_IF
M_par_top_5:= (V2+V3+V4+V8_1)*Vtop_3P*VL_air_abs/1000;    
M_air_pod_5:=V8_2*FB_p_air(T16)+V8_4/16*FB_p_air(T16); ; 
M_par_pod_5:= V8_2*VL_air_abs/1000+V8_4/16*VL_air_abs/1000;;    
M_air_5:=M_air_top_5+M_air_pod_5;
M_par_5:=M_par_top_5+M_par_pod_5;
Q_air_5:=M_air_top_5*FB_c_air(T_top)*T_top+M_air_pod_5*FB_c_air(T16)*T16;
Q_par_5:=M_par_top_5*FB_Q_par(T_top)+M_par_pod_5*FB_Q_par(T16);
V_air_5:=(M_air_top_5+M_air_pod_5)/FB_p_air(T_5); IF V_air_5=0 THEN V_air_5:=500; END_IF
V_par_5:=(M_par_top_5+M_par_pod_5)/FB_p_par(T_5);
vr_air_5:=k_t_air*3600*4/(V_air_5+V_par_5);
V_sh_5:= (V_air_5+V_par_5)/3600/6.1;
Q_pot_sh_5_in:= k_sh_in*1.0846*LREAL_TO_REAL(EXPT(V_sh_5,0.4932))*(12.6)*(T_5-T_st_sh_5_in)*0.06;
Q_POT_5:= Q_pot_sh_5_in*60;
Q_VL_AIR_5:=M_par_5*(FB_Q_par(T_top)-FB_Q_par(T_5));
Q_5:= Q_air_5+Q_par_5+Q_VL_AIR_5-Q_POT_5;
T_5:= Q_5/(M_air_5*FB_C_air(T_top)+M_par_5*FB_C_par(T_top)); IF T_5<>T_5 THEN T_5:=300; END_IF
VL_5:=V_par_5*1000/(V_air_5*FB_VL_air(T_5));
IF EN1 THEN 
T_rud_6:= T_rud_5-0.03*(T_5-T_rud_5)*vr_rud_5+0.0006;
Q_RUD_5:= M_rud_suh*C_rud*(T_rud_5-T_rud_6);
Q_VOT_5:= M_rud_suh*VL_rud_5*C_vod*(T_rud_5-T_rud_6);
ISP_5:= k_isp*vr_air_5*(T_5-T_rud_5)*k_PIT*FB_k_isp_vl(Vl_rud_5)*(1-VL_5);
Q_ISP_5:= ISP_5*C_isp;
Q_VL_ISP_5:=ISP_5*(FB_Q_par(T_5)-FB_Q_par(T_rud_5));
	IF (0.7*Q_5-Q_RUD_5-Q_VOT_5-Q_VL_AIR_5-Q_ISP_5-Q_VL_ISP_5)<0 THEN
	ISP_5:=0.7*(Q_5-Q_RUD_5-Q_VOT_5-Q_VL_AIR_5)/(C_isp+(T_5-T_rud_5)*FB_c_par(T_5));
	Q_ISP_5:= ISP_5*C_isp; 
	Q_VL_ISP_5:=ISP_5*(FB_Q_par(T_5)-FB_Q_par(T_rud_5));END_IF
	IF M_rud_suh>0 THEN VL_rud_6:= (VL_rud_5*M_rud_suh+ISP_5)/M_rud_suh; END_IF
ELSE VL_rud_5:=0; ISP_5:=0; Q_ISP_5:=0; T_rud_5:=0; Q_RUD_5:=0; Q_VOT_5:=0; ISP_5:=0; Q_VL_ISP_5:=0; END_IF
//Проверка значений
	IF Error THEN
	IF M_air_top_5>100000 THEN M_air_top_5:= 100000; Er_max_5:=TRUE; ELSIF M_air_top_5<0 THEN M_air_top_5:=1; Er_min_5:= TRUE; ELSIF M_air_top_5<>M_air_top_5 THEN M_air_top_5:=20000; Er_NaN_5:=TRUE; END_IF
	IF M_par_top_5>10000 THEN M_par_top_5:= 1000; Er_max_5:=TRUE; ELSIF M_par_top_5<0 THEN M_par_top_5:=1; Er_min_5:= TRUE; ELSIF M_par_top_5<>M_par_top_5 THEN M_par_top_5:=200; Er_NaN_5:=TRUE; END_IF
	IF M_air_pod_5>2000 THEN M_air_pod_5:= 2000; Er_max_5:=TRUE; ELSIF M_air_pod_5<0 THEN M_air_pod_5:=1; Er_min_5:= TRUE; ELSIF M_air_pod_5<>M_air_pod_5 THEN M_air_pod_5:=390; Er_NaN_5:=TRUE; END_IF
	IF M_par_pod_5>20 THEN M_par_pod_5:= 20; Er_max_5:=TRUE; ELSIF M_par_pod_5<0 THEN M_par_pod_5:=1; Er_min_5:= TRUE; ELSIF M_par_pod_5<>M_par_pod_5 THEN M_par_pod_5:=3; Er_NaN_5:=TRUE; END_IF
	IF M_air_5>100000 THEN M_air_5:= 100000; Er_max_5:=TRUE; ELSIF M_air_5<0 THEN M_air_5:=1; Er_min_5:= TRUE; ELSIF M_air_5<>M_air_5 THEN M_air_5:=20000; Er_NaN_5:=TRUE; END_IF
	IF M_par_5>10000 THEN M_par_5:= 10000; Er_max_5:=TRUE; ELSIF M_par_5<0 THEN M_par_5:=1; Er_min_5:= TRUE; ELSIF M_par_5<>M_par_5 THEN M_par_5:=200; Er_NaN_5:=TRUE; END_IF
	IF Q_air_5>50000000 THEN Q_air_5:= 50000000; Er_max_5:=TRUE; ELSIF Q_air_5<-1000000 THEN Q_air_5:=-1000000; Er_min_5:= TRUE; ELSIF Q_air_5<>Q_air_5 THEN Q_air_5:=13000000; Er_NaN_5:=TRUE; END_IF
	IF Q_par_5>5000000 THEN Q_par_5:= 5000000; Er_max_5:=TRUE; ELSIF Q_par_5<-10000 THEN Q_par_5:=-10000; Er_min_5:= TRUE; ELSIF Q_par_5<>Q_par_5 THEN Q_par_5:=790000; Er_NaN_5:=TRUE; END_IF
	IF V_air_5>500000 THEN V_air_5:= 500000; Er_max_5:=TRUE; ELSIF V_air_5<0 THEN V_air_5:=1; Er_min_5:= TRUE; ELSIF V_air_5<>V_air_5 THEN V_air_5:=500000; Er_NaN_5:=TRUE; END_IF
	IF V_par_5>10000 THEN V_par_5:= 10000; Er_max_5:=TRUE; ELSIF V_par_5<0 THEN V_par_5:=1; Er_min_5:= TRUE; ELSIF V_par_5<>V_par_5 THEN V_par_5:=60; Er_NaN_5:=TRUE; END_IF
	IF vr_air_5>100 THEN vr_air_5:= 100; Er_max_5:=TRUE; ELSIF vr_air_5<0 THEN vr_air_5:=1; Er_min_5:= TRUE; ELSIF vr_air_5<>vr_air_5 THEN vr_air_5:=1; Er_NaN_5:=TRUE; END_IF
	IF V_sh_5>100 THEN V_sh_5:= 100; Er_max_5:=TRUE; ELSIF V_sh_5<0 THEN V_sh_5:=1; Er_min_5:= TRUE; ELSIF V_sh_5<>V_sh_5 THEN V_sh_5:=2; Er_NaN_5:=TRUE; END_IF
	IF Q_pot_sh_5_in>10000 THEN Q_pot_sh_5_in:= 10000; Er_max_5:=TRUE; ELSIF Q_pot_sh_5_in<-10000 THEN Q_pot_sh_5_in:=-10000; Er_min_5:= TRUE; ELSIF Q_pot_sh_5_in<>Q_pot_sh_5_in THEN Q_pot_sh_5_in:=10000; Er_NaN_5:=TRUE; END_IF
	IF Q_POT_5>500000  THEN Q_POT_5:= 500000; Er_max_5:=TRUE; ELSIF Q_POT_5<-500000 THEN Q_POT_5:=-500000; Er_min_5:= TRUE; ELSIF Q_POT_5<>Q_POT_5 THEN Q_POT_5:=15000; Er_NaN_5:=TRUE; END_IF
	IF Q_VL_AIR_5>1000000 THEN Q_VL_AIR_5:= 1000000; Er_max_5:=TRUE; ELSIF Q_VL_AIR_5<-500000 THEN Q_VL_AIR_5:=-500000; Er_min_5:= TRUE; ELSIF Q_VL_AIR_5<>Q_VL_AIR_5 THEN Q_VL_AIR_5:=12000; Er_NaN_5:=TRUE; END_IF
