//Проверка значений переменных на NaN

// 1. Защита от выхода за границы разрядов
IF iDecimals < 0 THEN iDecimals := 0; END_IF;
IF iDecimals > 4 THEN iDecimals := 4; END_IF;

// 2. Преобразуем число в стандартную строку
sTemp := REAL_TO_STRING(rValue);

// 3. Поиск точки разделителя
iPos := FIND(sTemp, '.');

IF iPos > 0 THEN
    sIntPart := LEFT(sTemp, iPos - 1);
    sFracPart := RIGHT(sTemp, LEN(sTemp) - iPos);

    // Форматирование дробной части под заданное iDecimals
    IF iDecimals = 0 THEN
        sFracPart := '';
    ELSE
        IF LEN(sFracPart) > iDecimals THEN
            sFracPart := LEFT(sFracPart, iDecimals);
        ELSE
            WHILE LEN(sFracPart) < iDecimals DO
                sFracPart := CONCAT(sFracPart, '0');
            END_WHILE;
        END_IF;
        sFracPart := CONCAT('.', sFracPart); // Возвращаем точку обратно
    END_IF;
ELSE
    sIntPart := sTemp;
    sFracPart := '';
END_IF;

// 4. Расстановка пробелов в целой части (каждые 3 символа с конца)
iLen := LEN(sIntPart);
i := iLen - 3;

WHILE i > 0 DO
    // Пропускаем вставку пробела сразу после знака минус
    IF (i = 1 AND LEFT(sIntPart, 1) = '-') THEN
        EXIT; 
    END_IF;

    sIntPart := INSERT(sIntPart, ' ', i);
    i := i - 3;
END_WHILE;

// 5. Записываем результат работы прямо в имя функции
FB_Format_Number := CONCAT(sIntPart, sFracPart);

// Сброс счетчика перед каждым циклом опроса
iWebVisuCount := 0;

// Инициализация и запуск итератора по всем активным клиентам
VisuElems.g_ClientManager.BeginIteration();
pClient := VisuElems.g_ClientManager.GetNextClient();

WHILE pClient <> 0 DO
    // Проверяем, является ли тип подключения именно Web-визуализацией
    IF pClient^.GlobalData.ClientType = VisuElems.VisuElemBase.Visu_ClientType.WebVisualization THEN
        iWebVisuCount := iWebVisuCount + 1;
    END_IF

    // Переходим к следующему клиенту
    pClient := VisuElems.g_ClientManager.GetNextClient();
END_WHILE

Client:= int_to_real(iWebVisuCount);

IF rInput>=Minimal AND rInput <=Maximal THEN

// Инициализация при старте
IF NOT bInitialized OR bReset THEN
    FOR i := 0 TO 2 DO arrMed[i] := rInput; END_FOR;
    FOR i := 0 TO 9 DO arrBuffer[i] := rInput; END_FOR;
    bInitialized := TRUE;
    iIndex := 0;
END_IF;

// 1. СДВИГ БУФЕРА МЕДИАНЫ (запоминаем 3 последних такта)
arrMed[2] := arrMed[1];
arrMed[1] := arrMed[0];
arrMed[0] := rInput;

// 2. МЕДИАННАЯ ФИЛЬТРАЦИЯ НА 3 ТОЧКИ (выбираем среднее по величине)
IF ((arrMed[0] >= arrMed[1]) AND (arrMed[0] <= arrMed[2])) OR ((arrMed[0] <= arrMed[1]) AND (arrMed[0] >= arrMed[2])) THEN
    rFilteredIn := arrMed[0];
ELSIF ((arrMed[1] >= arrMed[0]) AND (arrMed[1] <= arrMed[2])) OR ((arrMed[1] <= arrMed[0]) AND (arrMed[1] >= arrMed[2])) THEN
    rFilteredIn := arrMed[1];
ELSE
    rFilteredIn := arrMed[2];
END_IF;

// 3. СКОЛЬЗЯЩЕЕ СРЕДНЕЕ (работает уже с «чистым» значением rFilteredIn)
arrBuffer[iIndex] := rFilteredIn;
iIndex := iIndex + 1;

IF iIndex > 9 THEN
    iIndex := 0;
END_IF;

rSum := 0.0;
FOR i := 0 TO 9 DO
    rSum := rSum + arrBuffer[i];
END_FOR;

rOutput := rSum / 10.0;
END_IF
